class Battle::SuccessState
  attr_accessor :typeMod
  attr_accessor :useState    # 0 - not used, 1 - failed, 2 - succeeded
  attr_accessor :protected
  attr_accessor :skill

  def initialize; clear; end

  def clear(full = true)
    @typeMod   = Effectiveness::NORMAL_EFFECTIVE_MULTIPLIER
    @useState  = 0
    @protected = false
    @skill     = 0 if full
  end

  def updateSkill
    case @useState
    when 1
      @skill = -2 if !@protected
    when 2
      if Effectiveness.super_effective?(@typeMod)
        @skill = 2
      elsif Effectiveness.normal?(@typeMod)
        @skill = 1
      elsif Effectiveness.not_very_effective?(@typeMod)
        @skill = -1
      else   # Ineffective
        @skill = -2
      end
    end
    clear(false)
  end
end

def initialize(*arg)
  super
  @battlersChanged      = true
  @mind                 = [0, 0]
  @skill                = [0, 0]
  @starthp              = [0, 0]
  @count                = 0
  @partyindexes         = [0, 0]
  @battleAI.battleArena = true
end

def pbCanSwitchIn?(idxBattler, _idxParty, partyScene = nil)
  partyScene&.pbDisplay(_INTL("{1} can't be switched out!", @battlers[idxBattler].pbThis))
  return false
end

def pbEORSwitch(favorDraws = false)
  return if favorDraws && @decision == 5
  return if !favorDraws && @decision > 0
  pbJudge
  return if @decision > 0
  2.times do |side|
    next if !@battlers[side].fainted?
    next if @partyindexes[side] + 1 >= self.pbParty(side).length
    @partyindexes[side] += 1
    newpoke = @partyindexes[side]
    pbMessagesOnReplace(side, newpoke)
    pbReplace(side, newpoke)
    pbOnBattlerEnteringBattle(side)
  end
end

def pbOnAllBattlersEnteringBattle
  @battlersChanged = true
  2.times do |side|
    @mind[side]    = 0
    @skill[side]   = 0
    @starthp[side] = battlers[side].hp
  end
  @count           = 0
  return super
end

def pbRecordBattlerAsActive(battler)
  @battlersChanged = true
  2.times do |side|
    @mind[side]    = 0
    @skill[side]   = 0
    @starthp[side] = @battlers[side].hp
  end
  @count           = 0
  return super
end

def pbCancelMoves(full_cancel = false)
  # Outragers get confused anyway if they are disrupted during their final
  # turn of using the move
  if @effects[PBEffects::Outrage] == 1 && pbCanConfuseSelf?(false) && !full_cancel
    pbConfuse(_INTL("{1} became confused due to fatigue!", pbThis))
  end
  # Cancel usage of most multi-turn moves
  @effects[PBEffects::TwoTurnAttack] = nil
  @effects[PBEffects::Rollout]       = 0
  @effects[PBEffects::Outrage]       = 0
  @effects[PBEffects::Uproar]        = 0
  @effects[PBEffects::Bide]          = 0
  @currentMove = nil if @effects[PBEffects::HyperBeam] == 0
  # Reset counters for moves which increase them when used in succession
  @effects[PBEffects::FuryCutter] = 0
end

def hp=(value)
  @hp = value.to_i
  @pokemon.hp = value.to_i if @pokemon
end

def fainted?; return @hp <= 0; end

def pbFaint(showMessage = true)
  if !fainted?
    PBDebug.log("!!!***Can't faint with HP greater than 0")
    return
  end
  return if @fainted   # Has already fainted properly
  @battle.pbDisplayBrief(_INTL("{1} fainted!", pbThis)) if showMessage
  PBDebug.log("[Pokémon fainted] #{pbThis} (#{@index})") if !showMessage
  @battle.scene.pbFaintBattler(self)
  @battle.pbSetDefeated(self) if opposes?
  pbInitEffects(false)
  # Reset status
  self.status      = :NONE
  self.statusCount = 0
  # Lose happiness
  if @pokemon && @battle.internalBattle
    badLoss = @battle.allOtherSideBattlers(@index).any? { |b| b.level >= self.level + 30 }
    @pokemon.changeHappiness((badLoss) ? "faintbad" : "faint")
  end
  # Reset form
  @battle.peer.pbOnLeavingBattle(@battle, @pokemon, @battle.usedInBattle[idxOwnSide][@index / 2])
  @pokemon.makeUnmega if mega?
  @pokemon.makeUnprimal if primal?
  # Do other things
  @battle.pbClearChoice(@index)   # Reset choice
  pbOwnSide.effects[PBEffects::LastRoundFainted] = @battle.turnCount
  if $game_temp.party_direct_damage_taken &&
     $game_temp.party_direct_damage_taken[@pokemonIndex] &&
     pbOwnedByPlayer?
    $game_temp.party_direct_damage_taken[@pokemonIndex] = 0
  end
  # Check other battlers' abilities that trigger upon a battler fainting
  pbAbilitiesOnFainting
  # Check for end of primordial weather
  @battle.pbEndPrimordialWeather
end

def initialize(scene, battle)
  @battletype  = battle[0]
  @properties  = battle[1]
  @rounds      = battle[2]
  @randomnums  = battle[3]
  @switches    = battle[4]
  @roundindex  = -1
  @randomindex = 0
  @switchindex = 0
  super(scene,
     Marshal.restore(@properties["party1"]),
     Marshal.restore(@properties["party2"]),
     RecordedBattle::PlaybackHelper.pbCreateTrainerInfo(@properties["player"]),
     RecordedBattle::PlaybackHelper.pbCreateTrainerInfo(@properties["opponent"])
  )
end

def pbStartBattle
  @party1starts          = Marshal.restore(@properties["party1starts"])
  @party2starts          = Marshal.restore(@properties["party2starts"])
  @internalBattle        = @properties["internalBattle"]
  @field.weather         = @properties["weather"]
  @field.weatherDuration = @properties["weatherDuration"]
  @canRun                = @properties["canRun"]
  @switchStyle           = @properties["switchStyle"]
  @showAnims             = @properties["showAnims"]
  @backdrop              = @properties["backdrop"]
  @backdropBase          = @properties["backdropBase"]
  @time                  = @properties["time"]
  @environment           = @properties["environment"]
  @items                 = Marshal.restore(@properties["items"])
  @rules                 = Marshal.restore(@properties["rules"])
  super
end

def pbClearChoice(idxBattler)
  @choices[idxBattler] = [] if !@choices[idxBattler]
  @choices[idxBattler][0] = :None
  @choices[idxBattler][1] = 0
  @choices[idxBattler][2] = nil
  @choices[idxBattler][3] = -1
end

def pbCancelChoice(idxBattler)
  # If idxBattler's choice was to use an item, return that item to the Bag
  if @choices[idxBattler][0] == :UseItem
    item = @choices[idxBattler][1]
    pbReturnUnusedItemToBag(item, idxBattler) if item
  end
  # If idxBattler chose to Mega Evolve, cancel it
  pbUnregisterMegaEvolution(idxBattler)
  # Clear idxBattler's choice
  pbClearChoice(idxBattler)
end
